<template><el-card v-if="report" class="eval-card" shadow="never"><template #header><div class="card-header"><span>评估报告</span><el-tag>{{splitText}}</el-tag></div></template><div class="metric-grid"><article v-for="item in metrics" :key="item.label"><strong :style="{color:item.color}">{{item.value}}</strong><span>{{item.label}}</span></article></div><el-table :data="perClass" stripe :row-class-name="rowClass"><el-table-column prop="class_name" label="类别"/><el-table-column label="AP@50"><template #default="{row}">{{percent(row.ap50)}}</template></el-table-column><el-table-column label="AP@50-95"><template #default="{row}">{{percent(row.ap50_95)}}</template></el-table-column><el-table-column label="评价"><template #default="{row}"><el-tag :type="row.ap50>=.7?'success':row.ap50>=.5?'warning':'danger'">{{row.ap50>=.7?'优秀':row.ap50>=.5?'良好':'需改进'}}</el-tag></template></el-table-column><template #empty><el-empty description="暂无每类 AP 数据"/></template></el-table><el-alert v-if="weakClasses.length" type="warning" :closable="false" :title="`弱势类别：${weakClasses.join('、')}，建议增加样本或检查标注质量`"/></el-card></template>
<script setup>import { computed } from 'vue';const props=defineProps({report:{type:Object,default:null},metrics:{type:Array,default:()=>[]},perClass:{type:Array,default:()=>[]},weakClasses:{type:Array,default:()=>[]}});const splitText=computed(()=>props.report?.split==='val'?'验证集':props.report?.split==='test'?'测试集':'训练集');const percent=v=>v==null?'-':`${(v*100).toFixed(1)}%`;const rowClass=({row})=>row.ap50<.5?'weak-row':''</script>
<style lang="scss" scoped>.eval-card{margin-top:$spacing-md;border-radius:$border-radius-lg}.card-header{display:flex;justify-content:space-between;align-items:center}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.metric-grid article{padding:14px;border:1px solid $border-color;border-radius:$border-radius-md;background:$surface-color-soft;text-align:center}.metric-grid strong,.metric-grid span{display:block}.metric-grid strong{font-size:20px}.metric-grid span{margin-top:5px;color:$text-secondary;font-size:12px}.el-alert{margin-top:12px}@media(max-width:700px){.metric-grid{grid-template-columns:repeat(2,1fr)}}</style>
